      "overviewMal": "സ്വാതന്ത്ര്യാനന്തര ആസൂത്രണ കമ്മീഷന്റെ രൂപീകരണവും മിശ്ര സമ്പദ്‌വ്യവസ്ഥയും. ഹാരോഡ്-ഡോമർ മാതൃകയിലുള്ള ഒന്നാം പഞ്ചവത്സര പദ്ധതി, പി.സി. മഹലനോബിസിന്റെ ഘനവ്യവസായ വികസന തന്ത്രം, ഹരിതവിപ്ലവം, ലൈസൻസ് രാജിന്റെ പരിമിതികൾ എന്നിവ ചർച്ച ചെയ്യുന്നു."
